from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    children: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        u = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = children[u][c]
            if nxt == -1:
                nxt = len(children)
                children[u][c] = nxt
                children.append([-1] * k)
                bad.append(False)
            u = nxt
        bad[u] = True

    fail = [0] * len(children)
    q: deque[int] = deque()
    for c in range(k):
        v = children[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            children[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = children[u][c]
            if v != -1:
                fail[v] = children[fail[u]][c]
                q.append(v)
            else:
                children[u][c] = children[fail[u]][c]

    good_idx: dict[int, int] = {}
    for u, is_bad in enumerate(bad):
        if not is_bad:
            good_idx[u] = len(good_idx)

    if 0 not in good_idx:
        return 0

    m = len(good_idx)
    mat = [[0] * m for _ in range(m)]
    for u, i in good_idx.items():
        for c in range(k):
            v = children[u][c]
            if not bad[v]:
                mat[i][good_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            row_a = a[i]
            row_res = res[i]
            for p in range(m):
                ap = row_a[p]
                if ap:
                    row_b = b[p]
                    for j in range(m):
                        row_res[j] += ap * row_b[j]
            for j in range(m):
                row_res[j] %= MOD
        return res

    vec = [0] * m
    vec[good_idx[0]] = 1

    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row = mat[i]
                    for j in range(m):
                        new_vec[j] += vi * row[j]
            vec = [x % MOD for x in new_vec]
        exp >>= 1
        if exp > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
